recipes.code:
{
  "inputs": [
    {
      "id": "holdings-api-key",
      "type": "promptString",
      "description": "Your Holdings API key. Create a free one in your Holdings workspace under Settings → API keys.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@getholdings/mcp@0.1.0"
      ],
      "env": {
        "HOLDINGS_API_KEY": "${input:holdings-api-key}",
        "HOLDINGS_API_BASE": "<holdings-api-base>"
      }
    }
  }
}
